 public LabSmokeTest(){super(MainActivity.class);}
 final Map<File,byte[]> backups=new HashMap<>();MainActivity a;
 @Override protected void setUp()throws Exception{super.setUp();getInstrumentation().sendKeyDownUpSync(KeyEvent.KEYCODE_WAKEUP);File base=getInstrumentation().getTargetContext().getFilesDir();for(String n:new String[]{"canvas.life.json","preferences.json","session.json","patterns.json"}){File f=new File(base,n);backups.put(f,f.exists()?java.nio.file.Files.readAllBytes(f.toPath()):null);}java.nio.file.Files.write(new File(base,"preferences.json").toPath(),"{\"theme\":\"Dark\",\"tour_seen\":true}".getBytes("UTF-8"));}
 @Override protected void tearDown()throws Exception{if(a!=null)try{runTestOnUiThread(()->{a.handler.removeCallbacksAndMessages(null);if(a.activeDialog!=null)a.activeDialog.dismiss();a.allowClose=true;a.finish();});getInstrumentation().waitForIdleSync();}catch(Throwable ignored){}for(Map.Entry<File,byte[]> item:backups.entrySet()){if(item.getValue()==null)item.getKey().delete();else java.nio.file.Files.write(item.getKey().toPath(),item.getValue());}super.tearDown();}
 TextView text(View v,String s){if(v instanceof TextView&&((TextView)v).getText().toString().equals(s))return (TextView)v;if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=0;i<group.getChildCount();i++){TextView found=text(group.getChildAt(i),s);if(found!=null)return found;}}return null;}
 ArrayList<EditText> fields(View v){ArrayList<EditText> all=new ArrayList<>();if(v instanceof EditText)all.add((EditText)v);if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=0;i<group.getChildCount();i++)all.addAll(fields(group.getChildAt(i)));}return all;}
 View dialog(){assertNotNull(a.activeDialog);assertTrue(a.activeDialog.isShowing());return a.activeDialog.getWindow().getDecorView();}
 void click(String s){TextView v=text(dialog(),s);assertNotNull("Missing dialog action: "+s,v);v.performClick();}
 void main(Runnable action)throws Throwable{runTestOnUiThread(action);getInstrumentation().waitForIdleSync();}
 void key(int code,int mods){a.dispatchKeyEvent(new KeyEvent(0,0,KeyEvent.ACTION_DOWN,code,0,mods));}
 void touch(int action,float x,float y){long t=android.os.SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(t,t,action,x,y,0);a.board.dispatchTouchEvent(e);e.recycle();}
 void screenshot(String name){try{View capture=(name.startsWith("user-save-")||name.startsWith("user-rules-"))?dialog():a.root;if(capture.getWidth()==0){int width=a.getResources().getDisplayMetrics().widthPixels,height=a.getResources().getDisplayMetrics().heightPixels;capture.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));capture.layout(0,0,width,height);}Bitmap b=Bitmap.createBitmap(capture.getWidth(),capture.getHeight(),Bitmap.Config.ARGB_8888);capture.draw(new android.graphics.Canvas(b));try(FileOutputStream out=new FileOutputStream(new File(a.getFilesDir(),"qa-"+name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}catch(Exception e){throw new AssertionError(e);}}
