 public void testTourAndPortableFiles()throws Throwable{a=getActivity();String json;try(InputStream in=getInstrumentation().getContext().getAssets().open("interop.life.json");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);json=out.toString("UTF-8");}final String data=json;main(()->{try{LifeEngine e=new LifeEngine();Documents.load(e,data);assertEquals(12,e.population());assertEquals(15,e.generation);LifeEngine copied=new LifeEngine();Documents.load(copied,Documents.save(e));assertEquals(e.live(),copied.live());Set<LifeEngine.Cell> before=copied.live();try{Documents.load(copied,"{\"rows\":4,\"cols\":4,\"grid\":[]}");fail("Accepted malformed file");}catch(JSONException expected){}assertEquals(before,copied.live());e.clear();e.place(new String[]{".O.","..O","OOO"},-50,-50);Set<LifeEngine.Cell> initial=e.live();for(int i=0;i<4;i++)e.step(true);Documents.load(copied,Documents.save(e));assertEquals(e.live(),copied.live());copied.restart();assertEquals(initial,copied.live());a.startTour();assertEquals(17,a.tour.length());for(int i=0;i<a.tour.length();i++){assertTrue(a.activeDialog.isShowing());assertNotNull("Tour must dim the main window",a.tourShade);if(i==5)assertTrue("Keyboard edit step highlights nothing",a.tourAlphas.isEmpty());else assertFalse("Tour step must spotlight controls",a.tourAlphas.isEmpty());if(i==6)assertNotNull(text(dialog(),a.tour.optJSONObject(i).optString("text").replace("{MOD}","Ctrl")));click(i==a.tour.length()-1?"Finish":"Next");}assertTrue(a.tourSeen);assertNull(a.tourShade);assertTrue(a.tourAlphas.isEmpty());a.startTour();assertEquals(0,a.tourIndex);click("Skip");}catch(Exception error){throw new AssertionError(error);}});}

 View findType(View v,Class<?> type){if(type.isInstance(v))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=findType(((ViewGroup)v).getChildAt(i),type);if(found!=null)return found;}return null;}
 double luminance(int color){double[] rgb={android.graphics.Color.red(color)/255.0,android.graphics.Color.green(color)/255.0,android.graphics.Color.blue(color)/255.0};for(int i=0;i<3;i++)rgb[i]=rgb[i]<=.04045?rgb[i]/12.92:Math.pow((rgb[i]+.055)/1.055,2.4);return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2];}
 void contrast(int text,int background){double a=luminance(text),b=luminance(background);assertTrue("Text contrast must be readable",(Math.max(a,b)+.05)/(Math.min(a,b)+.05)>=4.5);}
