 android.app.Instrumentation.ActivityMonitor documentMonitor(String action,int result,android.net.Uri uri)throws Exception{android.content.IntentFilter filter=new android.content.IntentFilter(action);filter.addCategory(android.content.Intent.CATEGORY_OPENABLE);if(!action.equals(android.content.Intent.ACTION_OPEN_DOCUMENT_TREE))filter.addDataType("application/json");android.content.Intent data=uri==null?null:new android.content.Intent().setData(uri);android.app.Instrumentation.ActivityMonitor monitor=new android.app.Instrumentation.ActivityMonitor(filter,new android.app.Instrumentation.ActivityResult(result,data),true);getInstrumentation().addMonitor(monitor);return monitor;}
